#include "ui_scene_fixture_decode.hpp"
#include <iostream>
using namespace mfrk::ui::scene;using namespace mfrk::ui::scene::test;
struct Case {std::string text;Constants numbers;Features features;std::uint64_t expected;};
std::uint64_t word64(Reader&r){std::uint64_t v=r.u32();return v|(std::uint64_t(r.u32())<<32);}
int main(int argc,char**argv)try{if(argc!=3)throw std::runtime_error("kind/file required");std::string kind=argv[1];const auto&id=identity(kind);auto r=Reader::file(argv[2],id);std::vector<Case>cases;for(unsigned c=0;c<id.count;++c){Case x;if(kind=="builtins"){x.text=string(r);auto n=r.u32();if(n>256)throw std::runtime_error("featurecount");while(n--)if(!x.features.emplace(string(r)).second)throw std::runtime_error("duplicate feature");}else{const auto length=r.u32(),n=r.u32();if(length>1024||n>256)throw std::runtime_error("expression bounds");for(unsigned j=0;j<length;++j)x.text.push_back(char(r.u8()));for(unsigned j=0;j<n;++j){auto key=string(r);auto value=r.f64();if(!std::isfinite(value)||!x.numbers.emplace(key,value).second)throw std::runtime_error("numericconstant");}}x.expected=word64(r);if((x.expected&0x7ff0000000000000ull)==0x7ff0000000000000ull)throw std::runtime_error("finiteexpressiongold");cases.push_back(std::move(x));}r.end();unsigned bad=0;for(const auto&x:cases){try{const auto value=evaluate_expression(x.text,x.numbers,kind=="builtins"?&x.features:nullptr);if(std::bit_cast<std::uint64_t>(value)!=x.expected)++bad;}catch(const std::exception&){++bad;}}std::cout<<kind<<": "<<cases.size()<<" original expressions, "<<bad<<" bit differences\n";return bad?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}
